/* Standalone design sandbox. No API, credentials, storage or real invitations. */
'use strict';
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => '¥ ' + (cents / 100).toLocaleString('zh-CN', {minimumFractionDigits:2, maximumFractionDigits:2});
const paths = {home:'M3 10 12 3l9 7v11H3Z M9 21v-8h6v8',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M15 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',history:'M3 11a9 9 0 1 1 3 8 M3 4v7h7 M12 7v5l3 2',chevron:'m8 10 4 4 4-4',arrow:'M4 12h16m-5-5 5 5-5 5',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M6 18 18 6',lock:'M5 11h14v10H5Z M8 11V7a4 4 0 0 1 8 0v4',wallet:'M3 6h18v15H3Z M3 6V3h14v3 M16 11h5v5h-5Z',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2Z M8 7h8M8 11h8M8 15h4',back:'m14 5-7 7 7 7'};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.receipt}"/></svg>`;
const people = [{id:'owner',name:'林悦',role:'所有者'},{id:'member',name:'陈远',role:'普通成员'},{id:'viewer',name:'林妈妈',role:'只读成员'}];
const person = id => people.find(p => p.id === id) || {name:'已退出成员',role:'只读成员'};
const avatar = id => `<span class="avatar ${id === 'member' ? 'blue' : ''}">${esc(person(id).name.slice(-1))}</span>`;
const personLabel = id => `<span class="person">${avatar(id)}${esc(person(id).name)}</span>`;
const makeRow = (id,title,amount,category,payer,method,date,author=payer,kind='expense',account='wallet') => ({id,title,amount,category,payer,method,date,author,kind,account,note:'',reimburse:method==='advance',settled:false,history:[`${person(author).name} 创建了这笔${kind==='contribution'?'成员投入':'支出'}`]});
const books = {
 family:{name:'温暖小家',budget:1000000,opening:{wallet:2000000,cash:120000},rows:[
  makeRow('f1','一周食材采购',32800,'餐饮','owner','advance','2026-09-11','member'),
  makeRow('f2','周末家庭聚餐',26800,'餐饮','member','advance','2026-09-10'),
  makeRow('f3','洗护与清洁用品',25200,'购物','owner','public','2026-09-09'),
  makeRow('f4','本月通勤',36000,'交通','member','public','2026-09-08'),
  makeRow('f5','本月其他餐饮',85200,'餐饮','owner','public','2026-09-07'),
  makeRow('f6','九月房租',280000,'居住','owner','public','2026-09-05'),
  makeRow('f7','九月家庭生活费',1000000,'成员投入','member','public','2026-09-01','member','contribution')],logs:['陈远记录了林悦垫付的食材采购 · 9月11日 10:32','林悦设置了九月家庭预算 ¥ 10,000.00 · 9月1日 09:00'],invites:[],plan:true},
 personal:{name:'个人账本',budget:200000,opening:{wallet:500000,cash:0},rows:[makeRow('p1','个人阅读订阅',2800,'学习','owner','public','2026-09-10')],logs:[],invites:[],plan:false}
};
const state = {book:'family',page:'overview',actor:'owner',selected:'f1',query:'',payer:'all',method:'all',detail:false};
const book = () => books[state.book];
const family = () => state.book==='family';
const role = () => person(state.actor).role;
const canWrite = () => !family() || role()!=='只读成员';
const canManage = () => !family() || ['所有者','管理员'].includes(role());
const canEdit = row => canWrite() && (canManage() || row.author===state.actor) && !row.settled;
const accountName = id => id==='cash'?'家庭备用金':family()?'家庭公共钱包':'个人钱包';
const methodName = row => row.method==='advance' ? (row.settled?'已报销':row.reimburse?'个人垫付 · 待报销':'个人付款 · 无需报销') : accountName(row.account);
function totals(){const rows=book().rows;return {expense:rows.filter(r=>r.kind==='expense').reduce((s,r)=>s+r.amount,0),income:rows.filter(r=>r.kind==='income').reduce((s,r)=>s+r.amount,0),advance:rows.filter(r=>r.method==='advance'&&r.reimburse&&!r.settled).reduce((s,r)=>s+r.amount,0)};}
function balance(account){return book().opening[account]+book().rows.reduce((sum,r)=>sum+(r.account===account&&r.method==='public'?(r.kind==='expense'?-r.amount:r.kind==='income'||r.kind==='contribution'?r.amount:0):0)-(r.settled&&r.settlementAccount===account?r.amount:0),0);}
function log(message){book().logs.unshift(`${person(state.actor).name} ${message} · 刚刚（演示）`);}
let toastTimer,returnFocus;
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3500);}
function showModal(title,body,footer=''){returnFocus=document.activeElement;$('modal').innerHTML=`<header class="modal-header"><h2 id="modal-title">${title}</h2><button data-action="close" aria-label="关闭对话框">${icon('close')}</button></header>${body}${footer}`;$('modal').showModal();}
function closeModal(){$('modal').close();if(returnFocus?.isConnected)returnFocus.focus();}
const footer = (label,action) => `<footer class="modal-footer"><button data-action="close">取消</button><button class="primary" data-action="${action}">${label}</button></footer>`;
const disabled = condition => condition?'':'disabled';
const pages = {overview:'总览',ledger:'流水',accounts:'账户',budget:'预算',members:'家庭管理',activity:'操作记录'};
function go(page){state.page=page;state.detail=false;render();window.scrollTo(0,0);}
function render(){
 $('persona').innerHTML=people.map(p=>`<option value="${p.id}" ${p.id===state.actor?'selected':''}>${p.name} · ${p.role}</option>`).join('');
 if(!family()&&['members','activity'].includes(state.page))state.page='overview';
 $('navigation').innerHTML=Object.entries(pages).filter(([key])=>key!=='activity'&&(family()||key!=='members')).map(([key,label])=>`<button data-go="${key}" class="${state.page===key?'active':''}" aria-current="${state.page===key?'page':'false'}">${label}</button>`).join('');
 $('profile').innerHTML=`${avatar(state.actor)}<div>${esc(person(state.actor).name)}<small>${family()?esc(role()):'仅自己可见'}</small></div>`;
 document.querySelectorAll('.rail button').forEach((b,i)=>{b.innerHTML=icon(['home','people','history'][i]);b.disabled=!family()&&i>0;});
 const heading={overview:[family()?'一起记账，生活有数。':'我的个人账本','九月的每一笔，都是生活的一部分。'],ledger:[family()?'家庭流水':'个人流水','付款人与记账人分别记录，每一笔都有清晰来路。'],accounts:['账户与垫款','公共资金和成员垫款分开管理，不读取私人账户。'],budget:['每月预算','让共同开支有计划，也为生活留一点余量。'],members:['家庭成员','一起管理家庭账目，各自保留个人空间。'],activity:['操作记录','保留每一次变更的操作者与内容。']}[state.page];
 $('main').innerHTML=`<div class="context"><div class="context-left"><button class="book-switch" data-action="switch">${icon(family()?'people':'lock')}${esc(book().name)}${icon('chevron')}</button><span class="pill ${family()?'warm':''}">${family()?'家庭共享账本':'私人账本'}</span></div><small>${family()?'3 位成员 · 家庭时区 UTC+08:00':'与家庭账本隔离'} · 人民币 CNY</small></div><div class="heading"><div><div class="eyebrow">${family()?'FAMILY LEDGER':'PERSONAL LEDGER'} / ${pages[state.page].toUpperCase()}</div><h1>${heading[0]}</h1><p>${heading[1]}</p></div><div class="heading-actions"><span class="period">2026 年 9 月 · 演示月份</span>${state.page==='members'?`<button class="primary" data-action="invite" ${disabled(canManage())}>${icon('plus')} 邀请成员</button>`:`<button class="primary" data-action="add" ${disabled(canWrite())}>${icon('plus')} 记一笔</button>`}</div></div>${family()&&role()==='只读成员'?'<div class="notice">当前为只读成员预览：可以查看家庭账目，不能记账或修改数据。</div>':''}${({overview,ledger,accounts,budget:budgetPage,members,activity})[state.page]()}<p class="footer-note">原型沙盒 · 所有操作仅在当前页面内演示，刷新即重置。不代表真实权限校验、云同步或邀请服务已实现。</p>`;
}
function stats(){const t=totals();return `<section class="metrics" aria-label="九月账本汇总">${[[family()?'公共资金余额':'账户余额',balance('wallet')+balance('cash'),'不包含成员私人账户'],['本月支出',t.expense,'个人垫付也计入家庭支出'],['预算剩余',book().budget-t.expense,`月度额度 ${money(book().budget)}`],['待报销垫款',t.advance,'报销不重复计入支出']].map(([n,v,sub],i)=>`<div class="metric"><span class="label">${n}</span><b class="num ${i===2&&v>=0?'green':''}">${money(v)}</b><small>${!family()&&i===0?'仅本人可见':!family()&&i===1?'仅统计当前个人账本':sub}</small></div>`).join('')}</section>`;}
function table(rows){return `<div class="table-wrap"><table><thead><tr><th>项目 / 日期</th><th>付款人</th><th class="account-col">资金来源</th><th class="recorder-col">记账人</th><th>金额</th></tr></thead><tbody>${rows.map(r=>`<tr class="${state.page==='ledger'&&state.selected===r.id?'selected':''}"><td><button class="item-link" data-row="${r.id}" aria-label="查看流水：${esc(r.title)}">${esc(r.title)}</button><small>${r.date.slice(5).replace('-','.')} · ${esc(r.category)}</small></td><td>${personLabel(r.payer)}</td><td class="account-col"><span class="pill ${r.method==='advance'?'warm':''}">${methodName(r)}</span></td><td class="recorder-col">${esc(person(r.author).name)}</td><td><b class="num ${r.kind==='income'?'green':''}">${r.kind==='expense'?'− ':r.kind==='income'?'+ ':''}${money(r.amount)}</b>${r.kind==='contribution'?'<small>成员投入 · 非收入</small>':''}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty"><h3>没有匹配的流水</h3><p>试试其他关键词或清除筛选。</p><button data-action="clear">清除筛选</button></div>':''}</div>`;}
function progress(value,total){const percent=total>0?value/total*100:0;return `<div class="budget-bar ${percent>100?'over':percent>=80?'warn':''}"><i style="width:${Math.min(100,Math.max(0,percent))}%"></i></div><div class="row"><small>已使用 ${percent.toFixed(1)}%</small><small>${percent>100?'已超预算':percent>=80?'接近预算上限':'预算内'}</small></div>`;}
function budgetCard(){return `<section class="panel"><div class="row"><h2>本月预算</h2><button class="text-button" data-go="budget">查看</button></div><div class="budget-number num">${money(totals().expense)}</div><small>月度额度 ${money(book().budget)}</small>${progress(totals().expense,book().budget)}<p class="section-note" style="margin-top:14px">成员投入、转账与报销不计入支出。</p></section>`;}
function taskCard(){const pending=book().rows.filter(r=>r.method==='advance'&&r.reimburse&&!r.settled);return `<section class="panel"><div class="row panel-head"><h2>一起处理</h2><span class="pill warm">${pending.length+(book().plan?1:0)} 项待办</span></div>${book().plan?`<div class="task"><div class="row"><b>音乐家庭订阅</b><b class="num">¥ 18.00</b></div><p>今天到期 · 尚未计入支出</p><button data-action="plan" ${disabled(canManage())}>查看并确认</button></div>`:''}${pending.map(r=>`<div class="task"><div class="row"><b>${esc(person(r.payer).name)}的垫款</b><b class="num">${money(r.amount)}</b></div><p>${esc(r.title)}</p><button data-row="${r.id}">核对垫款</button></div>`).join('')}${!pending.length&&!book().plan?'<p class="muted">目前没有待处理事项。</p>':''}</section>`;}
function overview(){return `<div class="privacy">${icon('lock')}<span>${family()?'共同记账，不等于公开全部。成员私人账户、个人流水和余额不会共享。':'这里只展示个人账本。家庭成员不会看到以下记录。'}</span></div>${stats()}<div class="dashboard"><div class="stack"><section class="panel"><div class="row panel-head"><div><h2>${family()?'最近的共同开支':'近期流水'}</h2><p class="section-note">${book().rows.length} 笔演示记录 · 点击项目可核对详情</p></div><button class="text-button" data-go="ledger">全部流水 ${icon('arrow')}</button></div>${table(book().rows.slice(0,5))}<div class="table-foot">${family()?'记录归家庭所有；署名保留每一位成员的参与。':'个人与家庭的统计相互独立。'}</div></section><section class="panel"><div class="row panel-head"><h2>支出花在哪里</h2><small>2026 年 9 月 · CNY</small></div>${categoryBars()}</section></div><aside class="stack">${budgetCard()}${taskCard()}</aside></div>`;}
function categoryBars(){const cats={};book().rows.filter(r=>r.kind==='expense').forEach(r=>cats[r.category]=(cats[r.category]||0)+r.amount);return Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([name,value])=>`<div class="category"><div class="row"><span>${esc(name)}</span><span class="num">${money(value)} <small>· ${(value/Math.max(1,totals().expense)*100).toFixed(1)}%</small></span></div><div class="budget-bar"><i style="width:${value/Math.max(1,totals().expense)*100}%"></i></div></div>`).join('')||'<p class="muted">记下第一笔支出后，这里会展示分类占比。</p>';}
function filtered(){return book().rows.filter(r=>(state.payer==='all'||r.payer===state.payer)&&(state.method==='all'||r.method===state.method)&&(r.title+' '+r.category+' '+r.note).includes(state.query.trim()));}
function filters(){return `<div class="filterbar"><label class="sr-only" for="search">搜索流水</label><input id="search" placeholder="搜索项目、分类或备注" value="${esc(state.query)}"><label class="sr-only" for="payer-filter">筛选付款人</label><select id="payer-filter"><option value="all">全部付款人</option>${people.map(p=>`<option value="${p.id}" ${state.payer===p.id?'selected':''}>${p.name}</option>`).join('')}</select><label class="sr-only" for="method-filter">筛选付款方式</label><select id="method-filter"><option value="all">全部付款方式</option><option value="public" ${state.method==='public'?'selected':''}>公共账户</option><option value="advance" ${state.method==='advance'?'selected':''}>个人垫付 / 付款</option></select><button data-action="clear" aria-label="清除流水筛选">重置</button></div>`;}
function ledger(){const rows=filtered();const selected=rows.find(r=>r.id===state.selected)||rows[0];if(selected)state.selected=selected.id;return `${filters()}<div class="ledger-layout ${state.detail?'show-detail':''}"><section class="panel"><div class="row panel-head"><h2>九月流水</h2><small>${rows.length} 笔 · 筛选支出 ${money(rows.filter(r=>r.kind==='expense').reduce((s,r)=>s+r.amount,0))}</small></div>${table(rows)}</section>${selected?detail(selected):'<aside class="panel"><p class="muted">没有可核对的记录。</p></aside>'}</div>`;}
function detail(r){return `<aside class="panel detail" aria-label="流水详情"><button class="mobile-back text-button" data-action="back">${icon('back')} 返回流水</button><div class="row panel-head"><span class="eyebrow">流水详情</span><span class="pill">${r.kind==='expense'?'支出':r.kind==='income'?'收入':'成员投入'}</span></div><div class="receipt-head"><span class="receipt-icon">${icon('receipt')}</span><h2>${esc(r.title)}</h2></div><div class="amount num">${r.kind==='expense'?'− ':''}${money(r.amount)}</div><span class="pill ${r.method==='advance'?'warm':''}">${methodName(r)}</span><div class="flow"><div><small>实际付款人</small><strong>${esc(person(r.payer).name)}</strong></div>${icon('arrow')}<div><small>记入账本</small><strong>${esc(book().name)}</strong></div></div><dl class="detail-list"><div><dt>记账人</dt><dd>${esc(person(r.author).name)}</dd></div><div><dt>发生日期</dt><dd>${r.date}</dd></div><div><dt>分类</dt><dd>${esc(r.category)}</dd></div><div><dt>资金来源</dt><dd>${r.method==='advance'?'私人账户 · 不共享详情':accountName(r.account)}</dd></div><div><dt>备注</dt><dd>${esc(r.note||'暂无备注')}</dd></div></dl>${r.method==='advance'?`<div class="privacy">${icon('lock')}<span>${r.settled?'已从公共钱包偿还，不再重复计入家庭支出。':'这笔开支已计入家庭支出，尚未扣减公共资金。'}</span></div>`:''}<h3>修改记录</h3><div style="margin-top:12px">${r.history.map(h=>`<div class="activity-item"><small>演示记录</small>${esc(h)}</div>`).join('')}</div><div class="detail-actions"><button data-edit="${r.id}" ${disabled(canEdit(r))}>编辑流水</button>${r.method==='advance'&&r.reimburse&&!r.settled?`<button class="primary" data-settle="${r.id}" ${disabled(canManage())}>登记报销</button>`:''}</div>${!canEdit(r)?`<p class="section-note">${r.settled?'已报销流水锁定编辑，避免金额与报销记录不一致。':'当前身份不能编辑此记录。普通成员只能编辑自己创建的流水。'}</p>`:''}</aside>`;}
function accounts(){return `${stats()}<div class="dashboard"><section class="stack"><div class="account-grid">${['wallet','cash'].filter(a=>family()||a==='wallet').map(a=>`<section class="panel"><div class="row"><h2>${accountName(a)}</h2>${icon('wallet')}</div><div class="account-number num">${money(balance(a))}</div><small>${a==='wallet'?'日常共同支出':'紧急备用 · 与日常钱包分开'} · CNY</small></section>`).join('')}</div><section class="panel"><h2>成员垫款</h2><p class="section-note">垫付已计入支出。登记报销只减少公共资金和应偿还金额。</p>${book().rows.filter(r=>r.method==='advance').map(r=>`<div class="member-row">${avatar(r.payer)}<div class="member-info"><b>${esc(person(r.payer).name)} · ${esc(r.title)}</b><small>${methodName(r)}</small></div><b class="num">${money(r.amount)}</b><button data-row="${r.id}">查看详情</button></div>`).join('')||'<div class="empty">没有成员垫款。</div>'}</section></section><aside class="panel"><h2>哪些钱属于家庭？</h2><ul class="permission-list"><li>公共钱包余额<span>共享</span></li><li>家庭备用金<span>共享</span></li><li>成员垫款金额<span>共享</span></li><li>成员私人银行卡<span>不共享</span></li><li>成员个人账本<span>不共享</span></li></ul><p class="muted">公共资金不等于家庭全部资产。私人余额不会被自动汇总。</p></aside></div>`;}
function budgetPage(){return `<div class="dashboard"><section class="panel"><div class="row"><div><h2>九月${family()?'家庭':'个人'}总预算</h2><p class="section-note">所有金额以人民币统计</p></div><button data-action="budget" ${disabled(canManage())}>调整预算</button></div><div class="account-number num">${money(book().budget)}</div>${progress(totals().expense,book().budget)}<div class="privacy" style="margin-top:24px"><span>已支出 ${money(totals().expense)}，${book().budget>=totals().expense?'还可支出':'已超出'} ${money(Math.abs(book().budget-totals().expense))}。报销、成员投入不重复计入。</span></div><h2 class="split-title">支出分类对比</h2>${categoryBars()}<p class="footer-note">本轮原型提供总预算调整；独立分类额度待后续设计。</p></section><aside>${taskCard()}</aside></div>`;}
function members(){return `<div class="privacy">${icon('lock')}<span>成员加入后可查看本家庭账本的全部历史，但不能查看任何人的个人账本。</span></div><div class="dashboard"><div class="stack"><section class="panel"><div class="row"><h2>家里的伙伴</h2><span class="pill">3 位成员</span></div>${people.map(p=>`<div class="member-row">${avatar(p.id)}<div class="member-info"><b>${p.name}${p.id===state.actor?' · 当前身份':''}</b><small>${p.id==='owner'?'创建于 2026.09.01':'加入于 2026.09.02'}</small></div><span class="pill ${p.role==='所有者'?'warm':''}">${p.role}</span><button data-member="${p.id}" ${disabled(state.actor==='owner'&&p.id!=='owner')}>权限</button></div>`).join('')}</section><section class="panel"><h2>邀请记录</h2>${book().invites.map(i=>`<div class="member-row"><div class="member-info"><b>${esc(i.name)}</b><small>${i.role} · 一次性 · 有效期 24 小时（演示）</small></div><span class="pill">${i.revoked?'已撤销':'待接受'}</span><button data-revoke="${i.id}" ${disabled(canManage()&&!i.revoked)}>撤销邀请</button></div>`).join('')||'<div class="empty"><p>还没有待接受的邀请。</p><button data-action="invite" '+disabled(canManage())+'>邀请一位家人</button></div>'}</section></div><aside class="panel"><h2>权限说明</h2><ul class="permission-list"><li><b>所有者</b><span>全部管理权限</span></li><li><b>管理员</b><span>管理账目、预算与邀请</span></li><li><b>普通成员</b><span>记账、编辑本人记录</span></li><li><b>只读成员</b><span>查看家庭账目</span></li></ul><p class="muted">第一版权限按角色分配。修改其他成员的记录会留下操作历史。</p><button class="text-button" data-go="activity" style="margin-top:16px">查看操作记录 ${icon('arrow')}</button></aside></div>`;}
function activity(){return `<section class="panel"><h2 class="panel-head">家庭操作时间线</h2>${book().logs.map(l=>`<div class="activity-item">${esc(l)}</div>`).join('')||'<p class="muted">暂无操作记录。</p>'}</section>`;}
function switchBook(){showModal('切换账本',`<div class="modal-body"><p class="muted" style="margin-bottom:18px">账本独立统计。切换不会移动流水或公开私人账户。</p>${Object.entries(books).map(([key,b])=>`<button class="choice" data-book="${key}">${icon(key==='family'?'people':'lock')}<div><b>${b.name}</b><small>${key==='family'?'家庭成员可见 · 3 位成员':'仅本人可见 · 个人账本示例'}</small></div><span class="pill">${state.book===key?'当前':'切换'}</span></button>`).join('')}</div>`);}
let editId=null;
function entry(id){if(!canWrite())return;const r=id?book().rows.find(r=>r.id===id):null;if(r&&!canEdit(r))return;editId=r?.id||null;showModal(r?'编辑流水':'记一笔共同开支',`<form id="entry-form"><div class="modal-body"><div class="privacy">${icon(family()?'people':'lock')}<span>记入 <b>${esc(book().name)}</b> · ${family()?'家庭成员可见':'仅本人可见'}。不会修改其他账本。</span></div><label class="field"><span>金额（CNY） *</span><input class="money-input" name="amount" type="number" min="0.01" max="99999999.99" step="0.01" required value="${r?r.amount/100:''}" placeholder="0.00" autofocus></label><div class="form-grid"><label class="field"><span>交易类型 *</span><select name="kind" id="entry-kind">${[['expense','支出'],['income','收入'],...(family()?[['contribution','成员投入（非收入）']]:[])].map(([v,n])=>`<option value="${v}" ${r?.kind===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>付款 / 经办人 *</span><select name="payer">${people.filter(p=>family()||p.id===state.actor).map(p=>`<option value="${p.id}" ${(r?.payer||state.actor)===p.id?'selected':''}>${p.name}</option>`).join('')}</select></label><label class="field full"><span>项目名称 *</span><input name="title" required maxlength="60" value="${esc(r?.title||'')}" placeholder="例如：一周食材采购"></label><label class="field"><span>分类 *</span><select name="category">${['餐饮','居住','购物','交通','学习','工资','其他'].map(n=>`<option ${r?.category===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>日期 *</span><input name="date" type="date" min="2026-09-01" max="2026-09-30" required value="${r?.date||'2026-09-11'}"><small>原型仅演示 2026 年 9 月。</small></label><label class="field full"><span>付款方式 *</span><select name="method" id="entry-method"><option value="public">${family()?'家庭公共账户':'个人钱包'}</option>${family()?`<option value="advance" ${r?.method==='advance'?'selected':''}>成员个人付款 / 垫付</option>`:''}</select></label><label class="field full" id="account-field"><span id="account-label">来源账户 *</span><select name="account"><option value="wallet">${accountName('wallet')}</option>${family()?`<option value="cash" ${r?.account==='cash'?'selected':''}>家庭备用金</option>`:''}</select></label><div id="advance-field" class="full" hidden><div class="privacy">${icon('lock')}<span>只记录付款成员和金额，不读取其私人账户。</span></div><label class="field"><span>是否需要家庭报销</span><select name="reimburse"><option value="yes">待家庭报销</option><option value="no" ${r&&!r.reimburse?'selected':''}>无需报销</option></select></label></div></div><label class="field"><span>备注</span><textarea name="note" maxlength="200">${esc(r?.note||'')}</textarea></label><small>记账人：${esc(person(r?.author||state.actor).name)}${r?' · 本次修改人：'+esc(person(state.actor).name):''}。转账表单不在本轮原型范围内。</small><p id="entry-error" class="error" role="alert"></p></div><footer class="modal-footer"><button type="button" data-action="close">取消</button><button class="primary" type="submit">${r?'保存修改':'保存到当前账本'}</button></footer></form>`);entryVisibility();}
function entryVisibility(){const isExpense=$('entry-kind').value==='expense';const method=$('entry-method');if(!isExpense)method.value='public';method.disabled=!isExpense;const advance=method.value==='advance';$('account-field').hidden=advance;$('advance-field').hidden=!advance;$('account-label').textContent=isExpense?'来源账户 *':'目标账户 *';}
function saveEntry(form){if(!canWrite())return;const data=new FormData(form);const raw=data.get('amount');if(!/^\d+(\.\d{1,2})?$/.test(raw)){$('entry-error').textContent='金额最多保留两位小数。';return;}const amount=Math.round(Number(raw)*100);const title=data.get('title').trim();if(!title){$('entry-error').textContent='请输入项目名称。';return;}const old=book().rows.find(r=>r.id===editId);if(old&&!canEdit(old))return;const kind=data.get('kind');const method=kind==='expense'?data.get('method'):'public';const next=makeRow(old?.id||'demo-'+crypto.randomUUID(),title,amount,kind==='contribution'?'成员投入':data.get('category'),data.get('payer'),method,data.get('date'),old?.author||state.actor,kind,data.get('account'));next.note=data.get('note').trim();next.reimburse=method==='advance'&&data.get('reimburse')==='yes';if(old){next.history=[...old.history,`${person(state.actor).name} 修改：${old.title} ${money(old.amount)} → ${next.title} ${money(amount)}；付款人 ${person(old.payer).name} → ${person(next.payer).name}`];book().rows[book().rows.indexOf(old)]=next;log(`修改了「${title}」`);}else{book().rows.unshift(next);log(`新增了「${title}」${money(amount)}`);}state.selected=next.id;state.query='';state.payer='all';state.method='all';state.page='ledger';state.detail=true;closeModal();render();toast('已保存到'+book().name+'（仅演示）');}
function invite(){if(!canManage())return;showModal('邀请家人一起记账',`<form id="invite-form"><div class="modal-body"><div class="privacy">${icon('people')}<span>加入 ${book().name} 后，可以查看家庭全部历史流水。个人账本仍然私密。</span></div><label class="field"><span>邀请备注 *</span><input name="name" required maxlength="30" placeholder="例如：爸爸"></label><label class="field"><span>加入后的角色</span><select name="role"><option>普通成员</option><option>只读成员</option></select></label><p class="muted">邀请一次有效，24 小时后过期，可随时撤销。管理员权限由所有者在加入后设置。</p><p class="notice" style="margin-top:18px">此处只生成演示邀请，不会发送邮件、短信或真实加入链接。</p></div><footer class="modal-footer"><button type="button" data-action="close">取消</button><button class="primary" type="submit">生成演示邀请</button></footer></form>`);}
function settle(id){const r=book().rows.find(r=>r.id===id);if(!canManage()||!r||r.settled||!r.reimburse)return;showModal('登记报销',`<div class="modal-body"><h3>${esc(r.title)} · ${money(r.amount)}</h3><div class="flow"><div><small>来源账户</small><strong>家庭公共钱包</strong></div>${icon('arrow')}<div><small>收款成员</small><strong>${esc(person(r.payer).name)}</strong></div></div><p>确认后，公共钱包减少 ${money(r.amount)}，待报销减少同等金额，家庭支出不变。</p><p class="section-note">仅登记已经完成的报销，不发起银行转账。原型不支持部分报销。</p></div>`,footer('确认登记（演示）','settle-confirm'));$('modal').dataset.target=id;}
function plan(){if(!canManage()||!book().plan)return;showModal('确认周期支出',`<div class="modal-body"><h3>音乐家庭订阅 · ¥ 18.00</h3><dl class="detail-list"><div><dt>计划日期</dt><dd>2026-09-11</dd></div><div><dt>来源账户</dt><dd>家庭公共钱包</dd></div><div><dt>分类</dt><dd>其他</dd></div></dl><p>确认后才新增支出并扣减公共钱包。记账人记录为当前成员。</p></div>`,footer('确认入账（演示）','plan-confirm'));}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.go){go(b.dataset.go);return;}
 if(b.dataset.row){const fromOverview=state.page!=='ledger';state.selected=b.dataset.row;state.query='';state.payer='all';state.method='all';state.page='ledger';state.detail=true;render();if(fromOverview)window.scrollTo(0,0);if(innerWidth<1160)document.querySelector('.detail')?.scrollIntoView({block:'start'});return;}
 if(b.dataset.book){state.book=b.dataset.book;state.query='';state.payer='all';state.method='all';state.selected=book().rows[0]?.id;closeModal();go('overview');return;}
 if(b.dataset.edit){entry(b.dataset.edit);return;}
 if(b.dataset.settle){settle(b.dataset.settle);return;}
 if(b.dataset.member&&state.actor==='owner'){const p=person(b.dataset.member);showModal('调整成员权限',`<form id="role-form"><div class="modal-body"><p>${esc(p.name)} · 当前角色：${p.role}</p><label class="field"><span>新的角色</span><select name="role">${['管理员','普通成员','只读成员'].map(r=>`<option ${p.role===r?'selected':''}>${r}</option>`).join('')}</select></label><p class="muted">改为只读后不能再新增或修改流水，历史记录保留。</p><input type="hidden" name="id" value="${p.id}"></div><footer class="modal-footer"><button type="button" data-action="close">取消</button><button class="primary">确认修改权限</button></footer></form>`);return;}
 if(b.dataset.revoke&&canManage()){const i=book().invites.find(i=>i.id===b.dataset.revoke);if(i&&!i.revoked){showModal('撤销邀请',`<div class="modal-body"><p>撤销给「${esc(i.name)}」的邀请？演示邀请码将失效，不影响现有成员。</p></div>`,footer('撤销邀请','revoke-confirm'));$('modal').dataset.target=i.id;}return;}
 switch(b.dataset.action){
 case 'close':closeModal();break;case 'switch':switchBook();break;case 'add':entry();break;case 'invite':invite();break;case 'back':state.detail=false;render();break;
 case 'clear':state.query='';state.payer='all';state.method='all';render();break;
 case 'budget':if(canManage())showModal('调整九月总预算',`<form id="budget-form"><div class="modal-body"><label class="field"><span>月度总额度（CNY） *</span><input name="amount" type="number" required min="0.01" step="0.01" max="99999999.99" value="${book().budget/100}"></label><p class="muted">只影响当前账本的 2026 年 9 月预算。不会修改既有流水。</p></div><footer class="modal-footer"><button type="button" data-action="close">取消</button><button class="primary">保存预算</button></footer></form>`);break;
 case 'plan':plan();break;
 case 'plan-confirm':if(canManage()&&book().plan){book().plan=false;book().rows.unshift(makeRow('plan-september','音乐家庭订阅',1800,'其他',state.actor,'public','2026-09-11'));log('确认了音乐家庭订阅');closeModal();render();toast('已确认入账（仅演示）');}break;
 case 'settle-confirm':{const r=book().rows.find(r=>r.id===$('modal').dataset.target);if(canManage()&&r&&!r.settled&&r.reimburse){r.settled=true;r.settlementAccount='wallet';r.history.push(`${person(state.actor).name} 登记报销 ${money(r.amount)}，公共钱包付款`);log(`登记报销「${r.title}」${money(r.amount)}`);closeModal();render();toast('报销已登记，支出未重复统计（仅演示）');}break;}
 case 'revoke-confirm':{const i=book().invites.find(i=>i.id===$('modal').dataset.target);if(canManage()&&i&&!i.revoked){i.revoked=true;log(`撤销了给「${i.name}」的邀请`);closeModal();render();toast('演示邀请已撤销');}break;}
 }
});
document.addEventListener('submit',event=>{event.preventDefault();const f=event.target;const d=new FormData(f);if(f.getAttribute('id')==='entry-form')saveEntry(f);
 if(f.id==='budget-form'&&canManage()){book().budget=Math.round(Number(d.get('amount'))*100);log('修改九月预算为 '+money(book().budget));closeModal();render();toast('预算已更新（仅演示）');}
 if(f.id==='invite-form'&&canManage()){const name=d.get('name').trim();if(!name){f.elements.name.setCustomValidity('请输入邀请备注');f.elements.name.reportValidity();return;}const invitation={id:crypto.randomUUID(),name,role:d.get('role'),revoked:false};book().invites.push(invitation);log(`生成了给「${name}」的演示邀请`);closeModal();state.page='members';render();showModal('演示邀请已生成',`<div class="modal-body"><p>${esc(name)} · ${invitation.role}</p><div class="invitation-code">DEMO-${invitation.id.slice(0,8).toUpperCase()}</div><p class="muted">仅用于展示邀请状态，不是真实可用的邀请码。成员不会实际加入家庭。</p></div><footer class="modal-footer"><button class="primary" data-action="close">返回成员管理</button></footer>`);}
 if(f.getAttribute('id')==='role-form'&&state.actor==='owner'){const p=person(d.get('id'));if(p.id==='owner')return;const before=p.role;p.role=d.get('role');log(`将${p.name}从${before}调整为${p.role}`);closeModal();render();toast('成员权限已更新（仅演示）');}
});
document.addEventListener('input',event=>{if(event.target.name==='name')event.target.setCustomValidity('');if(event.target.id==='search'){const position=event.target.selectionStart;state.query=event.target.value;state.detail=false;render();$('search').focus();$('search').setSelectionRange(position,position);}});
document.addEventListener('change',event=>{const e=event.target;if(e.id==='entry-kind'||e.id==='entry-method')entryVisibility();if(e.id==='payer-filter'||e.id==='method-filter'){state[e.id==='payer-filter'?'payer':'method']=e.value;state.detail=false;render();}if(e.id==='persona'){state.actor=e.value;if(!family())state.book='family';state.detail=false;render();}});
$('modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();go('overview');});
render();
